"""Casos docentes editables para documentar rutas pediátricas frecuentes.

Los ejemplos no sustituyen la valoración ni los protocolos institucionales. Se
cargan como punto de partida para que el profesional los adapte al paciente.
"""

from __future__ import annotations

from copy import deepcopy
from datetime import date


ANTECEDENTES_PEDIATRICOS = """NEONATALES: PRODUCTO DE SEGUNDA GESTACIÓN, EMBARAZO CONTROLADO, SIN COMPLICACIONES, NACE A TÉRMINO, SIN REQUERIMIENTO DE OXÍGENO U HOSPITALIZACIÓN, EGRESO CONJUNTO.
INMUNOLÓGICOS: VACUNAS AL DÍA SEGÚN PAI, SIN REACCIONES ATRIBUIDAS A VACUNAS.
ALIMENTACIÓN: ACORDE A LA EDAD.
PATOLÓGICOS, HOSPITALARIOS, FARMACOLÓGICOS, TRAUMÁTICOS, TÓXICOS, ALÉRGICOS, TRANSFUSIONALES Y QUIRÚRGICOS: NIEGA.
FAMILIARES: PADRE Y MADRE SANOS, NO CONSANGUÍNEOS.
PSICOSOCIALES: VIVIENDA CON TODOS LOS SERVICIOS, SIN EXPOSICIONES DE RIESGO RELEVANTES."""

REVISION_PEDIATRICA_COMPLETA = """CONSTITUCIONAL: SEGÚN CUADRO ACTUAL; SIN PÉRDIDA DE PESO DOCUMENTADA.
CARDIOVASCULAR: NIEGA CIANOSIS, SÍNCOPE, DOLOR PRECORDIAL O EDEMAS.
RESPIRATORIO: SÍNTOMAS Y HALLAZGOS DESCRITOS EN ENFERMEDAD ACTUAL Y EXAMEN FÍSICO; NIEGA APNEAS Y CIANOSIS.
DIGESTIVO: SEGÚN CUADRO ACTUAL; NIEGA HEMATEMESIS, HEMATOQUEZIA O MELENA.
URINARIO: DIURESIS SEGÚN CUADRO ACTUAL; NIEGA DISURIA, HEMATURIA O COLURIA.
NEUROLÓGICO: NIEGA CONVULSIONES, ALTERACIÓN DEL ESTADO DE CONCIENCIA O FOCALIZACIONES.
PIEL: NIEGA PETEQUIAS, EQUIMOSIS O LESIONES DIFERENTES A LAS DESCRITAS.
MÚSCULO-ESQUELÉTICO: NIEGA ARTRALGIAS, COJERA O EDEMAS."""


def _examen_pediatrico_completo(
    estado, *, nariz="PERMEABLE, SIN SECRECIONES.",
    orofaringe="MUCOSAS HÚMEDAS, SIN LESIONES.",
    torax="SIMÉTRICO, NORMOEXPANSIBLE, SIN TIRAJES.",
    cardiopulmonar="RUIDOS CARDÍACOS RÍTMICOS, SIN SOPLOS, MURMULLO VESICULAR CONSERVADO, SIN AGREGADOS PULMONARES.",
    abdomen="NO DISTENDIDO, RSHS PRESENTES, BLANDO, NO DOLOROSO, SIN SIGNOS DE IRRITACIÓN PERITONEAL.",
    genitales="ACORDES A LA EDAD, SIN ALTERACIONES EVIDENTES.",
    neurologico="ALERTA, SIN FOCALIZACIONES, SIN SIGNOS DE MENINGISMO, FUERZA Y TONO CONSERVADOS, SIN DÉFICIT.",
    piel="ROSADA, BIEN PERFUNDIDA, SIN LESIONES.",
):
    """Mantiene el examen por sistemas completo en cada caso docente."""
    return f"""{estado}

CABEZA: NORMOCÉFALA, SIN LESIONES.
OJOS: CONJUNTIVAS ROSADAS, ESCLERAS ANICTÉRICAS, PUPILAS ISOCÓRICAS Y REACTIVAS.
OÍDOS: SIN ALTERACIONES EVIDENTES.
NARIZ: {nariz}
OROFARINGE: {orofaringe}
CUELLO: MÓVIL, SIN ADENOPATÍAS.
TÓRAX: {torax}
CARDIOPULMONAR: {cardiopulmonar}
ABDOMEN: {abdomen}
GENITALES: {genitales}
EXTREMIDADES: EUTRÓFICAS, SIMÉTRICAS, SIN EDEMAS, LLENADO CAPILAR MENOR DE 2 SEGUNDOS.
NEUROLÓGICO: {neurologico}
PIEL: {piel}"""


def _caso(
    *, nombre, motivo, enfermedad, examen, diagnostico, busqueda, conducta,
    plan, signos, gpc="", aiepi="RESPIRATORIO", gpc_criterios=None,
    aiepi_criterios=None, antecedentes=ANTECEDENTES_PEDIATRICOS,
    revision=REVISION_PEDIATRICA_COMPLETA,
    fecha_nacimiento=date(2023, 1, 15), sexo="Femenino", justificacion="",
    familia="",
):
    cierres = {
        "EGRESO": (
            "POR EL ESTADO GENERAL CONSERVADO, LA ESTABILIDAD CLÍNICA Y LA "
            "AUSENCIA DE CRITERIOS ACTUALES DE HOSPITALIZACIÓN, SE DEFINE MANEJO "
            "AMBULATORIO. SE BRINDA INFORMACIÓN A PADRES O CUIDADOR RESPONSABLE SOBRE LAS MEDIDAS EN CASA, EL TRATAMIENTO "
            "INDICADO, LOS SIGNOS DE ALARMA Y LA OPORTUNIDAD DE RECONSULTA."
        ),
        "OBSERVACIÓN": (
            "SE DEFINE OBSERVACIÓN PEDIÁTRICA PARA VIGILANCIA CLÍNICA SERIADA, "
            "OBJETIVAR LA RESPUESTA AL MANEJO INICIAL Y REEVALUAR EL SITIO DE MANEJO. "
            "SE BRINDA INFORMACIÓN A PADRES O CUIDADOR RESPONSABLE SOBRE EL MOTIVO DE LA OBSERVACIÓN, LOS HALLAZGOS A VIGILAR "
            "Y EL PLAN DE REVALORACIÓN."
        ),
        "HOSPITALIZACIÓN": (
            "POR LOS HALLAZGOS CLÍNICOS DESCRITOS Y EL RIESGO DE DETERIORO, SE JUSTIFICA "
            "HOSPITALIZACIÓN PEDIÁTRICA PARA TRATAMIENTO, MONITORIZACIÓN Y REVALORACIÓN "
            "CLÍNICA. SE BRINDA INFORMACIÓN A PADRES O CUIDADOR RESPONSABLE SOBRE LA INDICACIÓN, EL PLAN TERAPÉUTICO Y LOS "
            "CRITERIOS DE EVOLUCIÓN."
        ),
    }
    analisis = (
        f"PACIENTE PEDIÁTRICO QUE CONSULTA POR {motivo}. {enfermedad} "
        f"{justificacion or 'LA VALORACIÓN CLÍNICA SE INTERPRETA EN CONJUNTO CON LOS SIGNOS VITALES, EL EXAMEN POR SISTEMAS Y LA EVOLUCIÓN.'} "
        f"{'SE DOCUMENTA APLICACIÓN DE LA RUTA GPC DE ' + gpc + ', CON LOS CRITERIOS CLÍNICOS REGISTRADOS EN ESTA HISTORIA. ' if gpc else ''}"
        f"{'SE DOCUMENTA EVALUACIÓN AIEPI ' + aiepi + ', INCLUYENDO SIGNOS GENERALES DE PELIGRO, CLASIFICACIÓN, CONSEJERÍA Y RECONSULTA SEGÚN CORRESPONDA. ' if aiepi else ''}"
        f"{cierres.get(conducta, '')}"
    )
    return {
        "nombre": nombre,
        "fecha_nacimiento": fecha_nacimiento,
        "sexo": sexo,
        "motivo": motivo,
        "enfermedad": enfermedad,
        "antecedentes": antecedentes,
        "revision": revision,
        "examen": examen,
        "diagnostico": diagnostico,
        "familia": familia,
        "busqueda_cie10": busqueda,
        "conducta": conducta,
        "plan": plan,
        "analisis": analisis,
        "signos": signos,
        "gpc": gpc,
        "aiepi": aiepi,
        "gpc_criterios": gpc_criterios or {},
        "aiepi_criterios": aiepi_criterios or {},
    }


